    cur, calls, sigs, up = ['2.1.280'], [], [], [True]
    def run(cmd, cur=cur, calls=calls, fail=fail, **kw):
        if cmd[0] == sys.executable:
            return SimpleNamespace(stdout=b'', stderr=b'')
        calls.append(os.path.basename(cmd[0]) + ' ' + ' '.join(cmd[1:]))
        if cmd[1] == '--version':
            return SimpleNamespace(stdout=(cur[0] + ' (Claude Code)\n').encode(), stderr=b'')
